WITH Src AS (SELECT * FROM order_items WHERE quantity <= 5 AND quantity BETWEEN 4 AND 8 AND order_id IN (9, 12, 15, 31)), summary AS (SELECT CASE WHEN quantity >= 9 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END AS quantity_bucket, ROUND(AVG(quantity), 2) AS avg_quantity, COUNT(unit_price) AS unit_price_count FROM Src GROUP BY CASE WHEN quantity >= 9 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END) SELECT quantity_bucket, unit_price_count FROM summary WHERE avg_quantity >= 72 ORDER BY quantity_bucket, unit_price_count DESC;
